`timescale 1ps / 1ps
`default_nettype none

import parameter_pkg::*;

// Optimal sorting network for 8 inputs
// 6 layers, 19 compare-exchange elements
// Generated by sorting network generator

// Compare-Exchange element for sorting
// Sorting order: bank_hash, seq, inc (decrements before increments)
// Note: seq_len is implicit from parameter_pkg (each sorter is for one SEQ_LEN)
// For synthesis sweeps: CE area is small, scales with BATCH_SIZE
module CE (
    input hashed_seq_update in_seq1,
    input hashed_seq_update in_seq2,
    output hashed_seq_update out_seq1,
    output hashed_seq_update out_seq2
);
    always_comb begin
        // Sort by: bank_hash -> seq -> inc (0 before 1)
        if ((in_seq2.bank_hash < in_seq1.bank_hash) ||
            (in_seq2.bank_hash == in_seq1.bank_hash && in_seq2.seq < in_seq1.seq) ||
            (in_seq2.bank_hash == in_seq1.bank_hash && in_seq2.seq == in_seq1.seq && in_seq2.inc < in_seq1.inc)) begin
            out_seq1 = in_seq2;
            out_seq2 = in_seq1;
        end else begin
            out_seq1 = in_seq1;
            out_seq2 = in_seq2;
        end
    end
endmodule

module SortingLayer0 (
    input hashed_seq_update input_batch [BATCH_SIZE-1:0],
    output hashed_seq_update output_batch [BATCH_SIZE-1:0]
);
CE ce0 (
    .in_seq1(input_batch[0]),
    .in_seq2(input_batch[2]),
    .out_seq1(output_batch[0]),
    .out_seq2(output_batch[2])
);
CE ce1 (
    .in_seq1(input_batch[1]),
    .in_seq2(input_batch[3]),
    .out_seq1(output_batch[1]),
    .out_seq2(output_batch[3])
);
CE ce2 (
    .in_seq1(input_batch[4]),
    .in_seq2(input_batch[6]),
    .out_seq1(output_batch[4]),
    .out_seq2(output_batch[6])
);
CE ce3 (
    .in_seq1(input_batch[5]),
    .in_seq2(input_batch[7]),
    .out_seq1(output_batch[5]),
    .out_seq2(output_batch[7])
);
endmodule

