module SeqSorter (
    input logic clk,
    input hashed_seq_update update_batch [BATCH_SIZE-1:0],
    output hashed_seq_update sorted_update_batch [BATCH_SIZE-1:0]
);
hashed_seq_update in0 [BATCH_SIZE-1:0];
hashed_seq_update out0 [BATCH_SIZE-1:0];
hashed_seq_update out0_reg [BATCH_SIZE-1:0];
hashed_seq_update out1 [BATCH_SIZE-1:0];
hashed_seq_update out1_reg [BATCH_SIZE-1:0];
hashed_seq_update out2 [BATCH_SIZE-1:0];
hashed_seq_update out2_reg [BATCH_SIZE-1:0];
hashed_seq_update out3 [BATCH_SIZE-1:0];
hashed_seq_update out3_reg [BATCH_SIZE-1:0];
hashed_seq_update out4 [BATCH_SIZE-1:0];
hashed_seq_update out4_reg [BATCH_SIZE-1:0];
hashed_seq_update out5 [BATCH_SIZE-1:0];
hashed_seq_update out5_reg [BATCH_SIZE-1:0];

SortingLayer0 l0 (.input_batch(in0), .output_batch(out0));
SortingLayer1 l1 (.input_batch(out0_reg), .output_batch(out1));
SortingLayer2 l2 (.input_batch(out1_reg), .output_batch(out2));
SortingLayer3 l3 (.input_batch(out2_reg), .output_batch(out3));
SortingLayer4 l4 (.input_batch(out3_reg), .output_batch(out4));
SortingLayer5 l5 (.input_batch(out4_reg), .output_batch(out5));

// Pipeline registers between layers to prevent DC from optimizing away logic
always @(posedge clk) begin
    in0 <= update_batch;
    out0_reg <= out0;
    out1_reg <= out1;
    out2_reg <= out2;
    out3_reg <= out3;
    out4_reg <= out4;
    out5_reg <= out5;
    sorted_update_batch <= out5_reg;
end
endmodule
